    /**
     * @return array<int, array{item_id: int, spell_id: int, item_spell_id: int, glyph_id: int, name: string, type: string, class_id: int, class_name: string, icon: string, quality: int, item_level: int}>
     */
    public static function getAll(): array
    {
        return self::GLYPHS;
    }

    /**
     * @return array{item_id: int, spell_id: int, item_spell_id: int, glyph_id: int, name: string, type: string, class_id: int, class_name: string, icon: string, quality: int, item_level: int}|null
     */
    public static function findByItemId(int $itemId): ?array
    {
        return self::GLYPHS[$itemId] ?? null;
    }

    /**
     * @return array{item_id: int, spell_id: int, item_spell_id: int, glyph_id: int, name: string, type: string, class_id: int, class_name: string, icon: string, quality: int, item_level: int}|null
     */
    public static function findBySpellId(int $spellId): ?array
    {
        foreach (self::GLYPHS as $glyph) {
            if ($glyph['spell_id'] === $spellId) {
                return $glyph;
            }
        }

        return null;
    }
